export function matchRanges(e,t){const n=[...new Set(t.filter(Boolean))].sort((e,t)=>t.length-e.length);if(!n.length)return[];const s=n.map(e=>e.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")).join("|");return[...e.matchAll(new RegExp(s,"giu"))].map(e=>({start:e.index,end:e.index+e[0].length,term:e[0].toLowerCase()}))}export function preview(e,t,n=150){e=String(e||"").replace(/\s+/gu," ").trim();const o=matchRanges(e,t);let s=0,c=-1,r=0;const i=new Map;for(let e=0;e<o.length;e++){const a=Math.max(0,o[e].start-35),d=a+n;for(;r<o.length&&o[r].start<d;){const e=o[r++].term;i.set(e,(i.get(e)||0)+1)}const l=i.size*100+r-e;l>c&&(c=l,s=a);const t=o[e].term;i.set(t,i.get(t)-1),i.get(t)||i.delete(t)}let a=Math.min(e.length,s+n);return s>0&&/[\uDC00-\uDFFF]/u.test(e[s])&&s--,a<e.length&&/[\uDC00-\uDFFF]/u.test(e[a])&&a--,{text:e.slice(s,a),leading:s>0,trailing:a<e.length,ranges:o.filter(e=>e.end>s&&e.start<a).map(e=>({start:Math.max(0,e.start-s),end:Math.min(a,e.end)-s}))}}export function appendHighlighted(e,t,n,s=matchRanges(t,n)){let o=0;for(const n of s){e.append(document.createTextNode(t.slice(o,n.start)));const i=document.createElement("mark");i.textContent=t.slice(n.start,n.end),e.append(i),o=n.end}e.append(document.createTextNode(t.slice(o)))}